// Read the raw form submission (flat field map).
const f = $input.first().json;

const errors = [];
const str = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const toList = (v) => str(v).split(',').map(s => s.trim()).filter(Boolean);

// ---- Required text fields ----
const required = ['recruiterName','officialEmail','companyName','jobTitle','role','employmentType','location','workMode','minimumCGPA','eligibleBranches','requiredSkills','jobDescription','applyLink'];
for (const key of required) {
  if (!str(f[key])) errors.push('Missing required field: ' + key);
}

// ---- Format validations ----
const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (str(f.officialEmail) && !emailRe.test(str(f.officialEmail))) errors.push('officialEmail is not a valid email');
if (str(f.hrContactEmail) && !emailRe.test(str(f.hrContactEmail))) errors.push('hrContactEmail is not a valid email');

const cgpa = Number(f.minimumCGPA);
if (str(f.minimumCGPA) && Number.isNaN(cgpa)) errors.push('minimumCGPA must be numeric');

let openings = null;
if (str(f.numberOfOpenings)) {
  openings = Number(f.numberOfOpenings);
  if (Number.isNaN(openings)) errors.push('numberOfOpenings must be numeric');
}

if (str(f.applicationDeadline) && Number.isNaN(Date.parse(str(f.applicationDeadline)))) {
  errors.push('applicationDeadline is not a valid date');
}

const urlRe = /^https?:\/\/.+/i;
if (str(f.applyLink) && !urlRe.test(str(f.applyLink))) errors.push('applyLink must be a valid URL (http/https)');

// ---- Build normalized job object ----
const jobId = 'JOB-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8).toUpperCase();
const nowIso = new Date().toISOString();

const job = {
  jobId,
  jobTitle: str(f.jobTitle),
  role: str(f.role),
  department: str(f.department),
  companyName: str(f.companyName),
  recruiterName: str(f.recruiterName),
  recruiterEmail: str(f.officialEmail),
  employmentType: str(f.employmentType),
  numberOfOpenings: openings,
  location: str(f.location),
  workMode: str(f.workMode),
  salaryOrStipend: str(f.salaryOrStipend),
  experienceRequired: str(f.experienceRequired),
  minimumCGPA: Number.isNaN(cgpa) ? 0 : cgpa,
  eligibleBranches: toList(f.eligibleBranches),
  requiredSkills: toList(f.requiredSkills),
  preferredSkills: toList(f.preferredSkills),
  jobDescription: str(f.jobDescription),
  responsibilities: toList(f.responsibilities),
  selectionProcess: toList(f.selectionProcess),
  applicationDeadline: str(f.applicationDeadline),
  joiningDate: str(f.joiningDate),
  applyLink: str(f.applyLink),
  hrContactEmail: str(f.hrContactEmail),
  createdAt: nowIso,
};

const recruiter = {
  recruiterName: str(f.recruiterName),
  officialEmail: str(f.officialEmail),
  phone: str(f.phone),
  designation: str(f.designation),
  companyName: str(f.companyName),
  companyWebsite: str(f.companyWebsite),
  careersUrl: str(f.careersUrl),
  companyLinkedIn: str(f.companyLinkedIn),
  companyDescription: str(f.companyDescription),
  createdAt: nowIso,
};

return [{ json: { isValid: errors.length === 0, errors, job, recruiter } }];

// ─────────── CONFIG (easy to change later) ───────────
const SKILL_MATCH_THRESHOLD = 50; // % of required skills a student must have
const OVERALL_SCORE_THRESHOLD = 60; // % overall weighted score to be eligible
const WEIGHTS = { cgpa: 20, branch: 20, role: 20, skills: 30, location: 10 };

// ─────────── Helpers ───────────
const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();
const asArray = (v) => Array.isArray(v) ? v : (v == null ? [] : String(v).split(',').map(x => x.trim()).filter(Boolean));

// ─────────── Job (single object) ───────────
const job = $('Validate & Normalize Job').first().json.job;
const jobId = $('Save Job').first().json.jobId || job.jobId;

const reqSkills = asArray(job.requiredSkills);
const reqSkillSet = reqSkills.map(norm);
const eligibleBranches = asArray(job.eligibleBranches).map(norm);
const jobRole = norm(job.role);
const jobTitle = norm(job.jobTitle);
const minCgpa = Number(job.minimumCGPA) || 0;
const jobLocations = asArray(job.location).map(norm); // location may be "Ahmedabad / Remote"
const splitLoc = jobLocations.flatMap(l => l.split('/').map(x => x.trim()).filter(Boolean));
const workMode = norm(job.workMode);

// ─────────── Students (many items) ───────────
const students = $('Find Active Students').all().map(i => i.json).filter(s => s && s.email);

const results = [];
for (const s of students) {
  const sSkills = asArray(s.skills);
  const sSkillSet = sSkills.map(norm);
  const sRoles = asArray(s.preferredRoles).map(norm);
  const sLocations = asArray(s.preferredLocations).map(norm);
  const sBranch = norm(s.branch);
  const sDegree = norm(s.degree);
  const sCgpa = Number(s.cgpa) || 0;

  // 1) Status
  const statusOk = norm(s.status) === 'active';

  // 2) CGPA
  const cgpaMatch = sCgpa >= minCgpa;

  // 3) Branch — exact match against branch OR degree (case-insensitive)
  const branchMatch = eligibleBranches.length === 0 ||
    eligibleBranches.some(b => b === sBranch || b === sDegree ||
      sBranch.includes(b) || b.includes(sBranch));

  // 4) Role — student's preferred roles overlap job role/title (whole-token aware)
  const roleMatch = sRoles.some(r => r === jobRole || r === jobTitle ||
    r.includes(jobRole) || jobRole.includes(r));

  // 5) Skills — exact token match, case-insensitive, no substring (Java != JavaScript)
  const matchedSkills = reqSkills.filter((rs, idx) => sSkillSet.includes(reqSkillSet[idx]));
  const missingSkills = reqSkills.filter((rs, idx) => !sSkillSet.includes(reqSkillSet[idx]));
  const reqCount = reqSkills.length;
  const matchedCount = matchedSkills.length;
  const skillPct = reqCount === 0 ? 100 : Math.round((matchedCount / reqCount) * 100);
  const skillMatch = skillPct >= SKILL_MATCH_THRESHOLD;

  // 6) Location / work mode compatibility
  let locationMatch = false;
  if (workMode === 'remote') {
    locationMatch = true; // remote work is location-agnostic
  } else {
    locationMatch = splitLoc.length === 0 ||
      splitLoc.some(jl => jl === 'remote' || sLocations.includes(jl)) ||
      sLocations.includes('remote');
  }

  // 7) Experience — permissive; freshers accepted unless job clearly needs seniority
  const expReq = norm(job.experienceRequired);
  const sExp = norm(s.experience);
  let experienceMatch = true;
  if (expReq && /(senior|3\+|4\+|5\+|[3-9] years|[3-9]\+ years)/.test(expReq)) {
    experienceMatch = /(1-2|2-3|0-1|[1-9] years)/.test(sExp);
  }

  // ─────────── Weighted score ───────────
  const score =
    (cgpaMatch ? WEIGHTS.cgpa : 0) +
    (branchMatch ? WEIGHTS.branch : 0) +
    (roleMatch ? WEIGHTS.role : 0) +
    Math.round((skillPct / 100) * WEIGHTS.skills) +
    (locationMatch ? WEIGHTS.location : 0);

  // Mandatory gates + thresholds
  const mandatory = statusOk && cgpaMatch && branchMatch && experienceMatch;
  const isEligible = mandatory && skillMatch && score >= OVERALL_SCORE_THRESHOLD;

  if (isEligible) {
    results.push({ json: {
      // student identity
      studentId: s._id || null,
      studentName: s.fullName,
      studentEmail: s.email,
      // match diagnostics (internal)
      isEligible,
      matchScore: score,
      skillMatchPercent: skillPct,
      matchedSkills,
      missingSkills,
      cgpaMatch, branchMatch, roleMatch, locationMatch, experienceMatch,
      // job context carried for the email + logging
      job,
      jobId,
    } });
  }
}

// If nobody matched, emit a single "no match" marker item so the workflow ends safely.
if (results.length === 0) {
  return [{ json: { isEligible: false, noMatch: true, job, jobId,
    message: 'No eligible students found for this job.' } }];
}

return results;

return [{ json: {
  status: 'done',
  message: 'Job posted and eligible students have been notified.',
} }];

const d = $('Build Email HTML').item.json;
return { json: {
  jobId: d.jobId,
  studentId: d.studentId,
  studentName: d.studentName,
  studentEmail: d.studentEmail,
  companyName: (d.job && d.job.companyName) || '',
  jobTitle: (d.job && d.job.jobTitle) || '',
  sentAt: new Date().toISOString(),
  status: 'sent',
  errorMessage: '',
} };

const d = $('Build Email HTML').item.json;
const err = ($json && $json.error) ? ($json.error.message || JSON.stringify($json.error)) : 'Email send failed';
return { json: {
  jobId: d.jobId,
  studentId: d.studentId,
  studentName: d.studentName,
  studentEmail: d.studentEmail,
  companyName: (d.job && d.job.companyName) || '',
  jobTitle: (d.job && d.job.jobTitle) || '',
  sentAt: new Date().toISOString(),
  status: 'failed',
  errorMessage: String(err),
} };

return [{ json: {
  status: 'no_match',
  message: 'No eligible students found for this job.',
  jobId: $input.first().json.jobId,
} }];

const errs = $input.first().json.errors || ['Invalid submission'];
return [{ json: {
  status: 'error',
  message: 'Job was not posted. Please fix the following and resubmit:',
  errors: errs,
} }];
